    if m1 <= 0 or m2 <= 0 or mf <= 0:
        continue
    total_initial = m1 + m2
    fraction = (total_initial - mf) / total_initial
    if fraction < 0:
        fraction = 0.0
    if fraction > 0.10:
        fails.append((ev.get('event', 'unknown'), fraction))

