import numpy as np, json, os, sys, math, random, statistics

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def isco_radius(M):
    """Prograde ISCO radius for a non-rotating BH (Bardeen et al. 1972):
    r_isco = 6 * GM / c**2 = 3 * r_s"""
    return 3 * schwarzschild_radius(M)

def horizon_area(r):
    """Area of a spherical horizon A = 4πr^2"""
    return 4 * math.pi * r**2

def hawking_temperature(M):
    """Hawking temperature T_H = ħ c^3 / (8π G k_B M)"""
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def planck_length():
    """Planck length l_P = sqrt(ħ G / c^3)"""
    return math.sqrt(hbar * G / c**3)

def random_masses(n=1000):
    """Generate n random astrophysical masses between 5 and 50 solar masses."""
    masses = [random.uniform(5, 50) * M_sun for _ in range(n)]
    return masses

def main():
    masses = random_masses()
    results = []
    for M in masses:
        r_s = schwarzschild_radius(M)
        r_isco = isco_radius(M)
        A = horizon_area(r_s)
        T = hawking_temperature(M)
        lP = planck_length()
        results.append({
            "mass_kg": M,
            "r_s_m": r_s,
            "r_isco_m": r_isco,
            "area_m2": A,
            "temperature_K": T,
            "planck_length_m": lP
        })
    # Pretty-print the list of dictionaries
    for idx, item in enumerate(results):
        print(f"Item {idx}: {item}")

if __name__ == "__main__":
    main()

